// Just one annotation to start the whole engine!
@SpringBootApplication
public class MyDemoApp {
    public static void main(String[] args) {
        SpringApplication.run(MyDemoApp.class, args);
    }
}

@Service
public class Chef {
    @Autowired
    private Vegetable delivery; // Spring 'injects' this automatically

    public void cook() { 
        delivery.chop(); 
    }
}

