public interface BookRepository extends JpaRepository<Book, Long> {
    // No SQL needed! Spring writes the query for you.
    List<Book> findByAuthor(String author);
}

@Component
public class OfficeWorker {
    @PostConstruct
    public void startWork() {
        System.out.println("I'm at my desk!");
    }

    @PreDestroy
    public void goHome() {
        System.out.println("Turning off the lights...");
    }
}

@Configuration
public class SecurityConfig {
    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) {
        return http.authorizeHttpRequests(auth -> 
            auth.requestMatchers("/vip/**").hasRole("ADMIN")
        ).build();
    }
}

@Aspect
@Component
public class LoggingAspect {
    @Before("execution(* com.app.service.*.*(..))")
    public void logBefore() {
        System.out.println("A method is about to run!");
    }
}
